// 복잡한 확률은 공식 말고 시뮬로 분포를 실측 (시드로 재현 가능)
function simulate(trials = 100000) {
  const samples = [];
  for (let i = 0; i < trials; i++) {
    let sum = 0;
    for (let a = 0; a < attacksPerRun; a++)
      sum += (rand() < critChance ? 200 : 100);   // 치명타 2배
    samples.push(sum);
  }
  samples.sort((a, b) => a - b);
  return {
    avg: mean(samples), sd: stddev(samples),
    p10: samples[Math.floor(trials * 0.10)],   // 하위 10%(최악)
    p90: samples[Math.floor(trials * 0.90)],   // 상위 10%
  };
}
// 특히 하위 5~10%(최악)가 견딜 만한지 확인하라
